// Plain-text first; the HTML part is a minimal escaped copy. Every dynamic value is either
// generated by the server (links) or a validated account name, and is escaped anyway.
const escapeHtml = value => String(value).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

function compose({ to, subject, lines, action }) {
  const text = [...lines, ...(action ? ['', `${action.label}:`, action.href] : []), '', '— ZeroTouch', 'Este mensaje es automático; no lo respondas.'].join('\n');
  const html = `<!doctype html><html lang="es"><body style="font-family:system-ui,sans-serif;color:#343942;background:#F4F4F6;line-height:1.5;padding:16px">${
    lines.map(line => line ? `<p>${escapeHtml(line)}</p>` : '').join('')}${
    action ? `<p><a href="${escapeHtml(action.href)}" style="display:inline-block;padding:10px 16px;background:#343942;color:#fff;border-radius:12px;text-decoration:none">${escapeHtml(action.label)}</a></p><p style="font-size:13px;color:#4b5563">Si el botón no funciona, copia este enlace en tu navegador:<br>${escapeHtml(action.href)}</p>` : ''
  }<p style="font-size:13px;color:#4b5563">— ZeroTouch. Este mensaje es automático; no lo respondas.</p></body></html>`;
  return { to, subject, text, html };
}

export const verificationMessage = ({ to, nombreUsuario, link }) => compose({
  to, subject: 'Confirma tu correo en ZeroTouch',
  lines: [`Hola, ${nombreUsuario}.`, 'Para activar tu cuenta de ZeroTouch, confirma este correo. El enlace vence en 24 horas y solo puede usarse una vez.',
    'Si no creaste esta cuenta, ignora este mensaje: no se activará.'],
  action: { label: 'Confirmar mi correo', href: link },
});

export const resetMessage = ({ to, nombreUsuario, link }) => compose({
  to, subject: 'Restablece tu contraseña de ZeroTouch',
  lines: [`Hola, ${nombreUsuario}.`, 'Recibimos una solicitud para restablecer la contraseña de tu cuenta. El enlace vence en 30 minutos y solo puede usarse una vez.',
    'Al cambiarla se cerrarán todas tus sesiones abiertas.', 'Si no lo solicitaste, ignora este mensaje: tu contraseña no cambiará.'],
  action: { label: 'Elegir una contraseña nueva', href: link },
});

export const existingAccountNotice = ({ to, nombreUsuario, resetPage }) => compose({
  to, subject: 'Intento de registro con tu correo en ZeroTouch',
  lines: ['Alguien intentó crear una cuenta de ZeroTouch con este correo, que ya pertenece a una cuenta.',
    `Tu nombre de usuario es: ${nombreUsuario}.`, 'Si fuiste tú, inicia sesión con ese nombre o recupera tu contraseña.',
    'Si no fuiste tú, no necesitas hacer nada: no se creó ningún acceso a tu cuenta.'],
  action: { label: 'Recuperar mi contraseña', href: resetPage },
});

export const passwordChangedNotice = ({ to, nombreUsuario }) => compose({
  to, subject: 'Tu contraseña de ZeroTouch cambió',
  lines: [`Hola, ${nombreUsuario}.`, 'La contraseña de tu cuenta se restableció y se cerraron todas las sesiones abiertas.',
    'Si no fuiste tú, solicita de inmediato una nueva recuperación de contraseña y avisa al administrador.'],
});
